fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len());
    for &c in str1 {
        if c.is_ascii_lowercase() {
            result.push(c.to_ascii_uppercase());
        } else if c.is_ascii_uppercase() {
            result.push(c.to_ascii_lowercase());
        } else {
            result.push(c);
        }
    }
    result
}

